mapper.select:
/* CastConfigMapper.retrieveAplyHstryList */ SELECT A.APLY_SN AS APLY_SN, A.SRC_FIX_ATRB_GROUP_ID AS SRC_FIX_ATRB_GROUP_ID, A.TGT_FIX_ATRB_GROUP_ID AS TGT_FIX_ATRB_GROUP_ID, NVL(A.TMNL_ID, ' ') AS TMNL_ID, NVL(A.TBL_NM, ' ') AS TBL_NM, NVL(A.SHEET_NM, ' ') AS SHEET_NM, NVL(A.APLY_ROW_CNT, 0) AS APLY_ROW_CNT, NVL(A.CNCL_YN, 'N') AS CNCL_YN, CASE WHEN NVL(A.CNCL_YN, 'N') = 'N' AND NOT EXISTS ( SELECT 1 FROM PMOWN.TH_PM_SMLT_ATRB_APLY_HSTRY N WHERE N.TGT_FIX_ATRB_GROUP_ID = A.TGT_FIX_ATRB_GROUP_ID AND NVL(N.TMNL_ID, ' ') = NVL(A.TMNL_ID, ' ') AND N.TBL_NM = A.TBL_NM AND NVL(N.CNCL_YN, 'N') = 'N' AND N.APLY_SN > A.APLY_SN ) THEN 'Y' ELSE 'N' END AS REVERTABLE_YN, NVL(TO_CHAR(A.FRST_REG_DT, 'YYYYMMDDHH24MISS'), ' ') AS FRST_REG_DT, NVL(A.FRST_RGTR_ID, ' ') AS FRST_RGTR_ID FROM PMOWN.TH_PM_SMLT_ATRB_APLY_HSTRY A WHERE 1 = 1 AND A.TGT_FIX_ATRB_GROUP_ID = #{tgtFixAtrbGroupId}
AND A.TMNL_ID = #{tmnlId}
AND A.SHEET_NM = #{sheetNm}
ORDER BY A.APLY_SN DESC

