/* CastConfigMapper.updateAplyHstryCancelBySet */
UPDATE PMOWN.TH_PM_SMLT_ATRB_APLY_HSTRY
SET CNCL_YN = 'Y',
    CNCL_DT = CURRENT_TIMESTAMP,
    CNCL_RGTR_ID = #{loginUserId}
WHERE APLY_SET_SN = #{aplySetSn}
AND CNCL_YN = 'N'
